package com.intentmanagement.app;
import com.intentmanagement.core.*;import com.intentmanagement.optimization.*;import com.intentmanagement.knowledge.*;import com.intentmanagement.dataset.*;import java.util.*;import java.nio.file.*;
public class SelfTest {
 public static void run(){int checks=0;try {
 QoSLossCalculator q=new QoSLossCalculator();if(Math.abs(q.mse(new double[]{60},new double[]{50})-100)>1e-9)throw new AssertionError("MSE");checks++;
 IntentManager m=new IntentManager(100);Intent a=m.submit("Reliable voice latency 50ms bandwidth 40Mbps");if(!a.status.equals("ACTIVE"))throw new AssertionError("first intent should fit");checks++;
 Intent b=m.submit("Video streaming latency 100ms bandwidth 35Mbps");if(!b.status.equals("ACTIVE"))throw new AssertionError("second intent should fit");checks++;
 Intent c=m.submit("Voice latency 50ms bandwidth 40Mbps");if(!c.status.equals("REJECTED"))throw new AssertionError("capacity conflict must reject");checks++;
 double[] w=new MGDAOptimizer().weights(new double[][]{{1,0},{0,1}},100);if(Math.abs(w[0]+w[1]-1)>1e-8||w[0]<0||w[1]<0)throw new AssertionError("MGDA simplex");checks++;
 SPSAOptimizer.Result s=new SPSAOptimizer().optimize(new double[]{0.1,0.9},p->Math.pow(p[0]-0.4,2)+Math.pow(p[1]-0.6,2),100,9);if(!Double.isFinite(s.finalLoss()))throw new AssertionError("SPSA finite");checks++;
 KG2EModel kg=new KG2EModel(4,1);double loss=kg.train(new KnowledgeGraph().all(),3,0.001,1);if(!Double.isFinite(loss))throw new AssertionError("KG2E finite");checks++;
 IntentManager kgManager=new IntentManager(100);Intent kgVoice=kgManager.submit("I need a voice call");if(Math.abs(kgVoice.targetLatencyMs-50)>1e-9||Math.abs(kgVoice.requiredBandwidthMbps-40)>1e-9)throw new AssertionError("KG-backed completion");checks++;
 IntentManager priority=new IntentManager(100);Intent low=priority.submit("Video streaming, latency 100ms, bandwidth 70Mbps");Intent critical=priority.submit("Emergency MCPTT, latency 20ms, bandwidth 40Mbps");if(!critical.status.equals("ACTIVE")||!low.status.equals("PREEMPTED"))throw new AssertionError("priority preemption novelty");checks++;
 try(JenaKnowledgeBase kb=new JenaKnowledgeBase(Path.of("data","ontology","intent-schema.ttl"))){var match=kb.match("Please enable mission-critical push-to-talk").orElseThrow(()->new AssertionError("Jena alias matching"));if(!match.service().equals("Emergency"))throw new AssertionError("Jena should match Emergency, got "+match.service());checks++;if(kb.profiles().size()<7)throw new AssertionError("RDF service profiles not loaded");checks++;String shacl=kb.validateWithShacl(Path.of("data","ontology","shapes","service-shapes.ttl"));if(!shacl.contains("PASSED"))throw new AssertionError("SHACL validation: "+shacl);checks++;String validIntent=kb.validateIntent(20,30,0.5,5,Path.of("data","ontology","shapes","service-shapes.ttl"));if(!validIntent.contains("PASSED"))throw new AssertionError("valid intent SHACL: "+validIntent);checks++;String invalidIntent=kb.validateIntent(-1,0,101,6,Path.of("data","ontology","shapes","service-shapes.ttl"));if(invalidIntent.contains("PASSED"))throw new AssertionError("invalid intent should fail SHACL");checks++;var metrics=new ServiceMatchingEvaluator().evaluate(Path.of("data","datasets","labelled_intent_matching.csv"),kb);if(metrics.total()!=200)throw new AssertionError("expected 200 held-out labelled examples, got "+metrics.total());if(metrics.accuracy()<0.90)throw new AssertionError("service matching accuracy too low: "+metrics.accuracy());checks++;}
 if(kgManager.latestEquationTrace().isEmpty())throw new AssertionError("equation pipeline should run on submitted intent");if(!kgManager.runEquationPipeline().contains("Eq.12"))throw new AssertionError("equation trace missing Eq.12");checks++;
 System.out.println("SELF-TEST PASSED: "+checks+" checks (including Apache Jena, SHACL, labelled matching evaluation and equation execution).");
 } catch(Exception ex){throw new RuntimeException("Self-test failed",ex);} }
}
